    Bug 1917485 - Do not scroll the message list when releasing a temporary selection. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D221641

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index 3d283913651..fc5c3c1b086 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -4992,7 +4992,7 @@ var threadPane = {
    * @param {boolean} [discard=true] - If false, the selection data is kept for
    *   another call of this function.
    * @param {boolean} [notify=true] - Whether a change in "select" event
-   *   should be fired.
+   *   should be fired and the current index should be scrolled into view.
    * @param {boolean} [expand=true] - Try to expand threads containing selected
    *   messages.
    */
@@ -5027,10 +5027,14 @@ var threadPane = {

     if (currentIndex == nsMsgViewIndex_None) {
       threadTree.currentIndex = -1;
-    } else {
+    } else if (notify) {
       threadTree.style.scrollBehavior = "auto"; // Avoid smooth scroll.
       threadTree.currentIndex = currentIndex;
       threadTree.style.scrollBehavior = null;
+    } else {
+      // Don't scroll at all.
+      threadTree._selection.currentIndex = currentIndex;
+      threadTree._updateCurrentIndexClasses();
     }

     // To avoid problems with restoreThreadState, do not discard any selection
diff --git a/mail/test/browser/folder-display/browser_middleClickMessages.js b/mail/test/browser/folder-display/browser_middleClickMessages.js
index 0c5706a3bef..95d10bfc7dd 100644
--- a/mail/test/browser/folder-display/browser_middleClickMessages.js
+++ b/mail/test/browser/folder-display/browser_middleClickMessages.js
@@ -52,6 +52,7 @@ var tabmail = document.getElementById("tabmail");
 var NUM_MESSAGES_IN_THREAD = 6;

 add_setup(async function () {
+  Services.prefs.setIntPref("mailnews.default_sort_order", 1);
   folder = await create_folder("RightClickMiddleClickA");
   threadedFolder = await create_folder("RightClickMiddleClickB");
   // We want exactly as many messages as we plan to delete, so that we can test
@@ -70,6 +71,7 @@ add_setup(async function () {
     threadedFolder.deleteSelf(null);
     reset_context_menu_background_tabs();
     reset_open_message_behavior();
+    Services.prefs.clearUserPref("mailnews.default_sort_order");
   });
 });
